import math

def special_factorial(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    def factorial(num):
        if num == 0:
            return 1
        return math.factorial(num)

    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)

    return result

